 const setup=s.stage==='setup'?[...root.children]:null,round=root.querySelector('.sk-round'),mission=root.querySelector('.sk-missions'),notes=root.querySelector('.sk-fold'),units=root.querySelector('.sk-unit-section'),originals=[...units?.querySelectorAll('.sk-unit')||[]],finish=root.querySelector('.sk-start'),header=root.querySelector('.sk-heading');
