 if(data.view!=='campaign'||data.campaignTab!=='session-detail')return;const c=typeof campaign==='function'&&campaign(),s=c?.sessions?.find(s=>s.id===data.selectedBattleSession),root=document.querySelector('.cp-campaign-page');if(!root||!s||!['pre-battle','battle','post-battle','completed'].includes(s.stage)||root.querySelector('.bp-workspace'))return;
 const stack=root.querySelector('.stack');if(!stack)return;const native=[...stack.children],participants=[...stack.querySelectorAll('.cp-participant')],back=stack.querySelector('[data-cp=session-back]'),round=stack.querySelector('[data-cp=round-complete]')?.closest('.section-heading'),bottom=stack.querySelector('.cp-session-bottom'),v=view(c,s),ctx=shell(v,root);ctx.nativeParticipants=participants;
 root.insertBefore(heading(v,back,ctx.brief),ctx.host);append(ctx.panels.get('round'),round,bottom);for(const node of native){if(node.classList.contains('ca-session-tools')||(v.preparing||s.stage==='post-battle')&&node.querySelector('.cp-participant')||s.stage==='completed'&&node.querySelector('.cp-report'))ctx.panels.get('round').append(node);else ctx.panels.get('operations').append(node);}stack.remove();roster(v,ctx);campaignMission(v,ctx);root.classList.add('bp-play-page','bp-campaign-play');window.UKI18n?.refresh(ctx.host);
